-- Generated by backend/tools/jeju-tagging/jeju_tagging.py
-- Text-only Gemini 2.5 tagging of Jeju places from SSAFY_TRIP_Dump.sql.

CREATE TEMP TABLE stg_enrichments
  (LIKE preference.place_tag_enrichments INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE stg_candidates
  (LIKE preference.place_tag_enrichment_candidates INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE stg_tags
  (LIKE preference.place_tag_enrichment_tags INCLUDING DEFAULTS) ON COMMIT DROP;


-- 같은 장소(provider, external_place_id)의 enrichment가 이미 있으면 그 행의 id를
-- 최종 id로 재사용한다. user_place_reactions / user_swipe_events /
-- synthetic_swipe_events 가 그 행을 참조하고 있어도 FK 위반 없이 갱신되고,
-- 다시 실행해도 결과가 같다.
CREATE TEMP TABLE enrichment_id_map ON COMMIT DROP AS
SELECT s.id AS dump_id, COALESCE(existing.id, s.id) AS final_id
FROM stg_enrichments s
LEFT JOIN LATERAL (
  SELECT e.id
  FROM preference.place_tag_enrichments e
  WHERE e.provider = s.provider AND e.external_place_id = s.external_place_id
  ORDER BY e.created_at
  LIMIT 1
) AS existing ON true;

CREATE UNIQUE INDEX ON enrichment_id_map (dump_id);

DELETE FROM preference.place_tag_enrichment_tags t
USING enrichment_id_map m WHERE t.enrichment_id = m.final_id;

DELETE FROM preference.place_tag_enrichment_candidates c
USING enrichment_id_map m WHERE c.enrichment_id = m.final_id;

  id, provider, external_place_id, source_modified_at, source_hash, status,
  model_provider, model_name, prompt_version, tag_dictionary_version,
  selection_policy_version, candidate_count, selected_count, enriched_at
)
SELECT m.final_id, s.provider, s.external_place_id, s.source_modified_at, s.source_hash, s.status,
       s.model_provider, s.model_name, s.prompt_version, s.tag_dictionary_version,
       s.selection_policy_version, s.candidate_count, s.selected_count, s.enriched_at
FROM stg_enrichments s
JOIN enrichment_id_map m ON m.dump_id = s.id
ON CONFLICT (id) DO UPDATE SET
  source_modified_at       = EXCLUDED.source_modified_at,
  source_hash              = EXCLUDED.source_hash,
  status                   = EXCLUDED.status,
  model_provider           = EXCLUDED.model_provider,
  model_name               = EXCLUDED.model_name,
  prompt_version           = EXCLUDED.prompt_version,
  tag_dictionary_version   = EXCLUDED.tag_dictionary_version,
  selection_policy_version = EXCLUDED.selection_policy_version,
  candidate_count          = EXCLUDED.candidate_count,
  selected_count           = EXCLUDED.selected_count,
  enriched_at              = EXCLUDED.enriched_at,
  updated_at               = now();

  id, enrichment_id, candidate_code, matched_tag_id, confidence, weight, selection_score, status, rationale
)
SELECT c.id, m.final_id, c.candidate_code, c.matched_tag_id, c.confidence, c.weight,
       c.selection_score, c.status, c.rationale
FROM stg_candidates c
JOIN enrichment_id_map m ON m.dump_id = c.enrichment_id;

  enrichment_id, tag_id, confidence, weight, preference_discrimination_snapshot,
  selection_score, rank_order, tag_statistic_run_id, rationale
)
SELECT m.final_id, t.tag_id, t.confidence, t.weight, t.preference_discrimination_snapshot,
       t.selection_score, t.rank_order, t.tag_statistic_run_id, t.rationale
FROM stg_tags t
JOIN enrichment_id_map m ON m.dump_id = t.enrichment_id;
